                            {
                                ["fallback"] = "If we commit, we hit hard and stay together.",
                                ["id"] = "guarded",
                                ["templateID"] = "convo.interaction.scene.horde_reply_brave.say.1.guarded",
                                ["textRole"] = "spoken_action",
                                ["translations"] = {
                                    ["EN"] = {
                                        "If we commit, we hit hard and stay together.",
